from fastapi import FastAPI
from fastapi.sse import ServerSentEvent
import pytest
from pydantic import ValidationError

def test_sse_newline_validation():
    # Test event with newline
    try:
        ServerSentEvent(event="hello\nworld")
        print("Failed: event with newline should have raised ValidationError")
    except ValidationError as e:
        print(f"Success: caught expected ValidationError for event: {e}")

    # Test id with newline
    try:
        ServerSentEvent(id="id\n123")
        print("Failed: id with newline should have raised ValidationError")
    except ValidationError as e:
        print(f"Success: caught expected ValidationError for id: {e}")

    # Test event with carriage return
    try:
        ServerSentEvent(event="hello\rworld")
        print("Failed: event with carriage return should have raised ValidationError")
    except ValidationError as e:
        print(f"Success: caught expected ValidationError for event (CR): {e}")

    # Test id with carriage return
    try:
        ServerSentEvent(id="id\r123")
        print("Failed: id with carriage return should have raised ValidationError")
    except ValidationError as e:
        print(f"Success: caught expected ValidationError for id (CR): {e}")

    # Test valid event
    try:
        ServerSentEvent(event="hello")
        print("Success: valid event passed")
    except ValidationError as e:
        print(f"Failed: valid event raised ValidationError: {e}")

    # Test valid id
    try:
        ServerSentEvent(id="123")
        print("Success: valid id passed")
    except ValidationError as e:
        print(f"Failed: valid id raised ValidationError: {e}")

if __name__ == "__main__":
    test_sse_newline_validation()

